;z-index:10;background:#11130f;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;color:#b9a66c;font-size:9px;letter-spacing:.25em;transition:opacity .5s}.loading.done{opacity:0;pointer-events:none}.loading-mark{font-size:37px;animation:pulse 1.4s infinite ease-in-out}@keyframes pulse{50%{opacity:.35;transform:scale(.9)}}
