import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x171b18);
scene.fog = new THREE.FogExp2(0x171b18, 0.027);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 90);
camera.position.set(0, 1.72, 8.5);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.outputColorSpace = THREE.SRGBColorSpace;

scene.add(new THREE.HemisphereLight(0x8c9a9d, 0x211c14, 1.15));
const moon = new THREE.DirectionalLight(0xb5c0bf, 1.25);
moon.position.set(-5, 12, 4); moon.castShadow = true;
moon.shadow.mapSize.set(1024, 1024); moon.shadow.camera.left = -17; moon.shadow.camera.right = 17; moon.shadow.camera.top = 19; moon.shadow.camera.bottom = -19;
moon.shadow.bias = -0.0007; scene.add(moon);

const mat = (color, roughness = 0.94, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const stone = mat(0x55544b), stoneDark = mat(0x363932), trim = mat(0x716b59), soot = mat(0x282925), iron = mat(0x393a35, .43, .76), gold = mat(0xc5a459, .34, .62), bone = mat(0xc5b99d), boneShadow = mat(0x827965), leather = mat(0x362b20), emberMat = new THREE.MeshBasicMaterial({ color: 0xff8a36 });
const worldMeshes = [];
function box(parent, size, position, material, cast = true, receive = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), material);
  mesh.position.set(...position); mesh.castShadow = cast; mesh.receiveShadow = receive; parent.add(mesh); return mesh;
}
function sphere(parent, radius, position, material, scale = [1,1,1], segments = 10) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, segments, Math.max(6, segments - 2)), material);
  mesh.position.set(...position); mesh.scale.set(...scale); mesh.castShadow = true; parent.add(mesh); return mesh;
}
function cylinder(parent, rt, rb, h, position, material, segments = 8) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, segments), material);
  mesh.position.set(...position); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}

// A hand-painted stone atlas built in the browser keeps the whole adventure self-contained.
function stoneTexture() {
  const c = document.createElement('canvas'); c.width = 512; c.height = 512;
  const ctx = c.getContext('2d'); ctx.fillStyle = '#494a43'; ctx.fillRect(0,0,512,512);
  let seed = 8291; const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  for (let y = 0; y < 512; y += 64) {
    const offset = (Math.floor(y / 64) % 2) * 55;
    for (let x = -56; x < 512; x += 112) {
      const shade = Math.floor(52 + rnd()*29); const bx = x + offset;
      ctx.fillStyle = `rgb(${shade},${shade},${shade-5})`; ctx.fillRect(bx+2,y+2,108,60);
      ctx.strokeStyle = 'rgba(190,181,155,.12)'; ctx.lineWidth = 2; ctx.strokeRect(bx+3,y+3,106,58);
      for (let n = 0; n < 28; n++) { const px=bx+rnd()*108, py=y+rnd()*60; ctx.fillStyle=`rgba(12,13,12,${rnd()*.18})`; ctx.fillRect(px,py,1+rnd()*5,1+rnd()*2); }
    }
  }
  const texture = new THREE.CanvasTexture(c); texture.wrapS = texture.wrapT = THREE.RepeatWrapping; texture.repeat.set(2.4,2.4); texture.colorSpace = THREE.SRGBColorSpace; texture.anisotropy = 4; return texture;
}
const stoneMap = stoneTexture();
const wallMaterial = new THREE.MeshStandardMaterial({ map: stoneMap, color: 0xb0aa99, roughness: 1 });
const floorMaterial = new THREE.MeshStandardMaterial({ map: stoneMap, color: 0x989589, roughness: 1 });

// Sunken crypt: a broad central hall with deep alcoves, pillars, and a sealed sanctum gate.
const floor = new THREE.Mesh(new THREE.PlaneGeometry(25, 34), floorMaterial); floor.rotation.x = -Math.PI/2; floor.position.set(0,0,-1.7); floor.receiveShadow = true; scene.add(floor);
box(scene,[25,.7,1],[0,-.35,12.5],stoneDark);
box(scene,[25,.7,1],[0,-.35,-18.5],stoneDark);
for (const side of [-1,1]) {
  const wall = new THREE.Mesh(new THREE.BoxGeometry(.8,7,32),wallMaterial); wall.position.set(side*12.3,3.15,-1.8); wall.castShadow=true; wall.receiveShadow=true; scene.add(wall);
  for(let z=11;z>=-16;z-=2.2){
    box(scene,[1.15,.42,2.22],[side*11.83,.23,z],stoneDark);
    // worn blocks and occasional cracked reliefs on the wall face
    if (Math.abs(z)%5<2) box(scene,[.13,1.4,.12],[side*11.78,1.2,z+.5],trim,false);
  }
}
for(let y=0;y<4;y++){
  const width=25-y*.15, height=1.35;
  for(let x=-12.3;x<12.5;x+=3.1){
    const offset=(y%2)*1.5;
    box(scene,[3.05,height,.62],[x+offset,6.2-y*.63,-1.8],wallMaterial);
  }
}
// Ribbed vault arches overhead.
for(let z=9;z>=-14;z-=5.6){
  for(const x of [-10.8,-7.2,-3.6,0,3.6,7.2,10.8]){
    const rib=box(scene,[.34,.4,1.1],[x,6.15,z],trim); rib.rotation.z=x*-.009;
